push.css:
.fxs .ag{--pr:26px;--pushA:#A4ADB7;--pushB:#3A424B;--pushC:#FFFFFF;--rim:#EEF2F6;--rimD:#3E4650;--pushFace:linear-gradient(180deg,#FFFFFF 0%,#F3F6F9 10%,#D6DCE3 30%,#A4ADB7 44%,#68727D 50%,#7D8792 56%,#C8CFD7 72%,#EEF2F6 88%,#FFFFFF 100%)}
.fxs .push.ag{box-shadow:inset 0 2px 0 rgba(255,255,255,.95),inset 0 -5px 8px rgba(40,50,60,.35),0 0 0 2.5px #FFFFFF,0 0 0 5px #8E98A3,0 0 0 8.5px #EEF2F6,0 0 0 10.5px #3E4650,
  0 8px 0 10.5px #9AA4AE,0 10px 0 10.5px #3A424B,0 0 26px 14px rgba(255,255,255,.55),0 0 64px 26px rgba(160,195,255,.35),0 22px 34px rgba(0,0,0,.45)}
.fxs .push.ag span{color:transparent;text-shadow:none}
.fxs .push.ag::after{border-color:rgba(232,240,255,.95)}
.fxs .ag .agf{position:absolute;left:0;top:0;width:200px;height:100px;border-radius:26px;overflow:hidden;pointer-events:none;font-style:normal}
.fxs .ag .agf svg{display:block;width:200px;height:100px}
.fxs .ag .agd{position:absolute;left:-40px;top:-30px;width:280px;height:160px;pointer-events:none;z-index:3;font-style:normal}
.fxs .ag .agd svg{display:block;width:280px;height:160px;overflow:visible}
.fxs .ag .agsh{transform-box:view-box;transform-origin:0 0;animation:fxagShine 1.8s ease-in-out infinite}
.fxs .ag .agsh.b{animation-delay:.16s}
@keyframes fxagShine{0%{transform:translateX(0)}55%,100%{transform:translateX(330px)}}
.fxs .ag .aggl{opacity:0;animation:fxagGl 1.6s ease-in-out infinite}
@keyframes fxagGl{0%,50%,100%{opacity:0;transform:scale(.2) rotate(0deg)}64%{opacity:1;transform:scale(1.15) rotate(45deg)}80%{opacity:.25;transform:scale(.5) rotate(80deg)}}
.fxs .ag .agrl{animation:fxagRim 1.3s linear infinite}
@keyframes fxagRim{from{stroke-dashoffset:0}to{stroke-dashoffset:-50}}
.fxs .ag .agtw{animation:fxagTw 2.2s ease-in-out infinite}
@keyframes fxagTw{0%,100%{opacity:.3;transform:scale(.45) rotate(0deg)}45%{opacity:1;transform:scale(1.15) rotate(30deg)}60%{opacity:.85;transform:scale(.9) rotate(40deg)}}
